export const TOUGH_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/tough-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getToughStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(TOUGH_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
